function _RecurseAddProp(prop, depth, _firstElement, _countOfElements)
{
    if(depth++ > 16 || prop == null || typeof prop == "function")
    {
        return;
    }
    if(typeof prop._attributes == "undefined")
    {
        prop._attributes = {};
    }

    if(typeof prop._attributes == "object")
    {
        if(typeof prop._attributes._firstElement == "undefined")
        {
            prop._attributes._firstElement = _firstElement;
        }
        if(typeof prop._attributes._countOfElements == "undefined")
        {
            prop._attributes._countOfElements = _countOfElements;
        }
    }
    for(child in prop)
    {
        if(child == "_attributes" || child == "_value")
        {
            continue;
        }
        _RecurseAddProp(prop[child], depth, _firstElement, _countOfElements);
    }
    return;
}

function _ShouldNotSerialize(parentObject, propName)
{
    return((typeof parentObject[propName] == "function") || !parentObject.propertyIsEnumerable(propName));
}

//-----------------------------------------------------------------------------
// File: CaptionShaders.fx
//
// Desc: HLSL shaders used for rendering effects in captions
// 
// Copyright (c) Microsoft Corporation. All rights reserved.
//-----------------------------------------------------------------------------

//-----------------------------------------------------------------------------
// Vertex shader output structures
//-----------------------------------------------------------------------------
struct VSOUT
{
float4 Position : POSITION;
float2 uvTex : TEXCOORD;
};

//--------------------------------------------------------------------------------------
// Vertex shader constants
//--------------------------------------------------------------------------------------
uniform float4x4 WorldViewProj;
float4 LightTint;
float4 DarkTint;
float4 TextTint;
float4 TextColor;
float OpacityMultiplier;
float BorderSize;
sampler2D inputSampler
{
AddressU = Clamp;
AddressV = Clamp;
MinFilter = Anisotropic;
MagFilter = Anisotropic;
};

//--------------------------------------------------------------------------------------
// Name: CaptionVertexShader
//--------------------------------------------------------------------------------------
VSOUT CaptionVertexShader
(
const float2 Position0 : POSITION0,
const float2 uv : TEXCOORD0,
uniform float offsetX,
uniform float offsetY
)
{
VSOUT Output;
float4 pos; // position in screen space
pos = mul(float4(Position0.x, Position0.y, 0, 1), WorldViewProj);
pos.x -= .5 + offsetX*BorderSize;
pos.y -= .5 + offsetY*BorderSize;
pos.z = 0;

Output.Position=pos;

Output.uvTex.x = uv.x;
Output.uvTex.y = uv.y;

return Output;
}

//--------------------------------------------------------------------------------------
// Name: CaptionNormalPixelShader
//--------------------------------------------------------------------------------------
float4 CaptionNormalPixelShader
(
VSOUT vsOut
) : COLOR
{
float4 val = tex2D(inputSampler,vsOut.uvTex);
val*=TextTint*TextColor;
val.a*=OpacityMultiplier;	
return val;	
}

//--------------------------------------------------------------------------------------
// Name: CaptionOffsetPixelShader
//--------------------------------------------------------------------------------------
float4 CaptionOffsetPixelShader
(
VSOUT vsOut,
uniform bool fLightTint
) : COLOR
{
float4 val = tex2D(inputSampler,vsOut.uvTex);
if (fLightTint)
val*=LightTint;
else
val*=DarkTint;    

val.a*=OpacityMultiplier;	
return val;	
}

technique NormalCaptions
{
pass P0
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,0);
PixelShader  = compile ps_2_0 CaptionNormalPixelShader(); 
ViewportEnable = FALSE;
}
}

technique OutlineCaptions
{
pass P0
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
ViewportEnable = FALSE;
}
pass P1
{          
VertexShader = compile vs_2_0 CaptionVertexShader(1,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P2
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P3
{          
VertexShader = compile vs_2_0 CaptionVertexShader(1,1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P4
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P5
{          
VertexShader = compile vs_2_0 CaptionVertexShader(1,0);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P6
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,0);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P7
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P8
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,0);
PixelShader  = compile ps_2_0 CaptionNormalPixelShader(); 
}
}

technique DropShadowCaptions
{
pass P0
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(false); 
ViewportEnable = FALSE;
}
pass P1
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,0);
PixelShader  = compile ps_2_0 CaptionNormalPixelShader(); 
}
}

technique LoweredOrRaisedCaptions
{
pass P0
{          
VertexShader = compile vs_2_0 CaptionVertexShader(1,1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
ViewportEnable = FALSE;
}
pass P1
{          
VertexShader = compile vs_2_0 CaptionVertexShader(1,0);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P2
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(true); 
}
pass P3
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(false); 		
}
pass P4
{          
VertexShader = compile vs_2_0 CaptionVertexShader(1,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(false); 
}
pass P5
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(false); 
}
pass P6
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,-1);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(false); 
}
pass P7
{          
VertexShader = compile vs_2_0 CaptionVertexShader(-1,0);
PixelShader  = compile ps_2_0 CaptionOffsetPixelShader(false); 
}
pass P8
{          
VertexShader = compile vs_2_0 CaptionVertexShader(0,0);
PixelShader  = compile ps_2_0 CaptionNormalPixelShader(); 
}
}
